import { createHash } from 'node:crypto';
import { z } from 'zod';

/**
 * Key material arrives as base64 (locally: `openssl rand -base64 32`) or as a long random
 * alphanumeric string generated by AWS Secrets Manager (also valid base64). Either way it is
 * decoded and must carry at least `bytes` bytes.
 */
const keyMaterial = (bytes: number) =>
  z
    .string()
    .regex(/^[A-Za-z0-9+/]+={0,2}$/, 'must be base64 or alphanumeric')
    .transform((s) => Buffer.from(s, 'base64'))
    .refine((b) => b.length >= bytes, { message: `must decode to at least ${bytes} bytes` });

/** AES-256 needs exactly 32 bytes: use them as-is, otherwise derive with SHA-256. */
const aesKey = keyMaterial(32).transform((b) => (b.length === 32 ? b : createHash('sha256').update(b).digest()));

const schema = z
  .object({
    APP_ENV: z.enum(['development', 'test', 'staging', 'production']).default('development'),
    PORT: z.coerce.number().int().default(3000),

    // Either a full URL (local, CI) or the parts AWS provides from the RDS secret.
    DATABASE_URL: z.string().min(1).optional(),
    DB_HOST: z.string().min(1).optional(),
    DB_PORT: z.coerce.number().int().default(5432),
    DB_NAME: z.string().min(1).optional(),
    DB_USER: z.string().min(1).optional(),
    DB_PASSWORD: z.string().min(1).optional(),
    /** Path to the RDS CA bundle. When set, TLS is required and the server certificate is verified. */
    DB_SSL_CA_FILE: z.string().min(1).optional(),
    DB_POOL_MAX: z.coerce.number().int().min(1).max(100).default(10),

    MIGRATE_ON_BOOT: z
      .enum(['true', 'false'])
      .default('false')
      .transform((v) => v === 'true'),
    AUTH_ISSUER: z.string().default('PROJECT_NAME'),
    AUTH_JWT_SECRET: keyMaterial(32),
    AUTH_OTP_PEPPER: keyMaterial(32),
    AUTH_FIELD_KEY: aesKey,
    MESSAGING_PROVIDER: z.enum(['sandbox']).default('sandbox'),
    COLLECTIONS_PROVIDER: z.enum(['sandbox']).default('sandbox'),
    COLLECTIONS_WEBHOOK_SECRET: z.string().min(16),
    /** Absolute URL of the signing page; signer links are this plus #token. */
    SIGNING_BASE_URL: z.url().optional(),
    /** S3 bucket for executed contracts (Object Lock). Without it documents are kept in memory (dev/test only). */
    CONTRACTS_BUCKET: z.string().min(3).optional(),
    /** Only tests may turn this off; see LendingService. */
    REQUIRE_SIGNED_CONTRACT: z
      .enum(['true', 'false'])
      .default('true')
      .transform((v) => v === 'true'),
    REQUIRE_ASSET_AT_HANDOVER: z
      .enum(['true', 'false'])
      .default('true')
      .transform((v) => v === 'true'),
  })
  .superRefine((c, ctx) => {
    const parts = c.DB_HOST && c.DB_NAME && c.DB_USER && c.DB_PASSWORD;
    if (!c.DATABASE_URL && !parts) {
      ctx.addIssue({
        code: 'custom',
        path: ['DATABASE_URL'],
        message: 'set DATABASE_URL, or all of DB_HOST, DB_NAME, DB_USER, DB_PASSWORD',
      });
    }
    if ((c.APP_ENV === 'production' || c.APP_ENV === 'staging') && !c.CONTRACTS_BUCKET) {
      ctx.addIssue({ code: 'custom', path: ['CONTRACTS_BUCKET'], message: 'required in staging and production (signed contracts must be archived)' });
    }
    if (c.APP_ENV !== 'test' && c.APP_ENV !== 'development' && !c.REQUIRE_SIGNED_CONTRACT) {
      ctx.addIssue({ code: 'custom', path: ['REQUIRE_SIGNED_CONTRACT'], message: 'can only be false in development or test' });
    }
    if (c.APP_ENV !== 'test' && c.APP_ENV !== 'development' && !c.REQUIRE_ASSET_AT_HANDOVER) {
      ctx.addIssue({ code: 'custom', path: ['REQUIRE_ASSET_AT_HANDOVER'], message: 'can only be false in development or test' });
    }
    if ((c.APP_ENV === 'production' || c.APP_ENV === 'staging') && !c.DB_SSL_CA_FILE) {
      ctx.addIssue({ code: 'custom', path: ['DB_SSL_CA_FILE'], message: 'required in staging and production (verified TLS to RDS)' });
    }
    if (c.APP_ENV === 'production' && c.COLLECTIONS_PROVIDER === 'sandbox') {
      ctx.addIssue({
        code: 'custom',
        path: ['COLLECTIONS_PROVIDER'],
        message: 'sandbox collections is not allowed in production: no real money would be collected',
      });
    }
    if (c.APP_ENV === 'production' && c.MESSAGING_PROVIDER === 'sandbox') {
      ctx.addIssue({
        code: 'custom',
        path: ['MESSAGING_PROVIDER'],
        message: 'sandbox messaging is not allowed in production: OTPs would never reach users',
      });
    }
  });

export type AppConfig = z.infer<typeof schema>;

/** Fails fast at startup with every missing or malformed variable listed. Values are never logged. */
export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const parsed = schema.safeParse(env);
  if (!parsed.success) {
    const problems = parsed.error.issues.map((i) => `  ${i.path.join('.')}: ${i.message}`).join('\n');
    throw new Error(`Invalid configuration:\n${problems}`);
  }
  return parsed.data;
}

export const APP_CONFIG = Symbol('APP_CONFIG');
